-7d3a-a236-901c9fd3db2f","description":"22","correct_answer":false},{"id":"01a218eb-5631-7287-9c66-f68660e4e858","description":"66","correct_answer":false},{"id":"01a218eb-5631-7aa4-a62d-e06727b96afa","description":"88","correct_answer":false}]},{"id":"01a218eb-5631-7cea-8885-46549f230033","locale":"ptBR","category":"01a2135e-b9ba-7fbd-8736-4a658c8d2151","question":"Na astronomia, qual \u00e9 o termo usado para medir o brilho das estrelas?","difficulty":3,"explanation":"A magnitude aparente mede o brilho de uma estrela visto da Terra; ao contr\u00e1rio da magnitude absoluta, ela depende tanto da luminosidade intr\u00ednseca da estrela quanto de sua dist\u00e2ncia.","alternatives":[{"id":"01a218eb-5631-7343-badc-add0bd832e12","description":"Magnitude aparente","correct_answer":true},{"id":"01a218eb-5631-7446-8b46-1ea638f654bc","description":"Luminosidade aparente","correct_answer":false},{"id":"01a218eb-5631-7195-ae9c-aba9fb6c3649","description":"Intensidade aparente","correct_answer":false},{"id":"01a218eb-5631-7c8c-9cdf-36a0753d09b4","description":"Radia\u00e7\u00e3o aparente","correct_answer":false}]},{"id":"01a218eb-5631-7e03-bd2a-65712c207333","locale":"ptBR","category":"01a2135e-b9ba-7fbd-8736-4a658c8d2151","question":"De onde \u00e9 obtido o medicamento card\u00edaco digit\u00e1lico?","difficulty":3,"explanation":"A dedaleira cont\u00e9m glicos\u00eddeos card\u00edacos, como a digoxina, que podem fortalecer as contra\u00e7\u00f5es do cora\u00e7\u00e3o, mas s\u00e3o t\u00f3xicos em doses excessivas.","alternatives":[{"id":"01a218eb-5631-7db8-b930-9634e583b17a","description":"Dedalheira","correct_answer":true},{"id":"01a218eb-5631-7293-956b-93ad76005055","description":"Beladona","correct_answer":false},{"id":"01a218eb-5631-7925-abea-af8cc4875dcd","description":"Bambu","correct_answer":false},{"id":"01a218eb-5631-77c1-b33d-10f512316ad7","description":"Coco","correct_answer":false}]},{"id":"01a218eb-5631-716c-b0b9-206ab6706365","locale":"ptBR","category":"01a2135e-b9ba-7fbd-8736-4a658c8d2151","question":"Qual \u00e9 a palavra para designar um grupo de bois?","difficulty":3,"explanation":"Um jugo pode significar um par de bois trabalhando juntos, bem como o dispositivo de madeira usado para atrelar os animais.","alternatives":[{"id":"01a218eb-5631-7b82-9d91-86dcbe360f3e","description":"Um jugo","correct_answer":true},{"id":"01a218eb-5631-7143-b898-32eba8dde002","description":"Um rebanho","correct_answer":false},{"id":"01a218eb-5631-79ae-a4db-b1b47e98201e","description":"Um rebanho","correct_answer":false},{"id":"01a218eb-5631-76f0-a340-253e5d16fa77","description":"Um grupo","correct_answer":false}]},{"id":"01a218eb-5631-71f3-9bcd-11a73432bba0","locale":"ptBR","category":"01a2135e-b9ba-7fbd-8736-4a658c8d2151","question":"Cite o nome da maior ave viva.","difficulty":3,"explanation":"As avestruzes t\u00eam apenas dois dedos em cada pata, menos do que qualquer outra ave.","alternatives":[{"id":"01a218eb-5631-72cf-997a-6eb46bed3d54","description":"Avestruz","correct_answer":true},{"id":"01a218eb-5631-7ae2-b585-4e1680421156","description":"Pav\u00e3o","correct_answer":false},{"id":"01a218eb-5631-7264-810c-5ffc50e66229","description":"Emu","correct_answer":false},{"id":"01a218eb-5631-7f8a-a733-84ebffb8caca","description":"Pinguim-imperador","correct_answer":false}]},{"id":"01a218eb-5631-773c-bcbd-7f509735a638","locale":"ptBR","category":"01a2135e-b9ba-7fbd-8736-4a658c8d2151","question":"Qual \u00e9 a palavra para designar um grupo de potros?","difficulty":3,"explanation":"Um potro \u00e9 um cavalo jovem do sexo masculino, e \u201crag\u201d \u00e9 um substantivo coletivo pouco comum para designar potros.","alternatives":[{"id":"01a218eb-5631-7ffa-9300-5d5ae747f4a3","description":"Um rag","correct_answer":true},{"id":"01a218eb-5631-7e7e-b9f4-e2981c24cc63","description":"Um ninho","correct_answer":false},{"id":"01a218eb-5631-7fc6-8c3c-50fb64e1fda2","description":"Um rel\u00f3gio","correct_answer":false},{"id":"01a218eb-5631-7b2b-a61f-d892a1c0a8f3","description":"Um garanh\u00e3o","correct_answer":false}]},{"id":"01a218eb-5631-75a0-ba24-a5f506d4c8ad","locale":"ptBR","category":"01a2135e-b9ba-7fbd-8736-4a658c8d2151","question":"Qual \u00e9 a palavra para designar um grupo de girafas?","difficulty":3,"explanation":"\u201cManada\u201d \u00e9 o nome coletivo para girafas. Os grupos de girafas costumam ter uma estrutura flex\u00edvel, com indiv\u00edduos entrando e saindo ao longo do tempo.","alternatives":[{"id":"01a218eb-5631-7c95-92a7-eed09a098a5e","description":"Um rebanho","correct_answer":true},{"id":"01a218eb-5631-7391-a484-4f9ecd20a624","description":"Uma pregui\u00e7a","correct_answer":false},{"id":"01a218eb-5631-7f72-b34f-f77a6d3f12cd","description":"Um bando","correct_answer":false},{"id":"01a218eb-5631-7ade-9017-4ac3387a2b72","description":"Um cete","correct_answer":false}]},{"id":"01a218eb-5631-775d-9f38-a07350638b8e","locale":"ptBR","category":"01a2135e-b9ba-7fbd-8736-4a658c8d2151","question":"Como se chama uma gata?","difficulty":3,"explanation":"Uma \u201crainha\u201d \u00e9 uma gata, especialmente aquela usada para reprodu\u00e7\u00e3o; um macho adulto costuma ser chamado de \u201ctom\u201d.","alternatives":[{"id":"01a218eb-5631-72dd-8525-b0e467cc5c49","description":"Uma rainha","correct_answer":true},{"id":"01a218eb-5631-742e-acf9-08b9d909d872","description":"Uma oper\u00e1ria","correct_answer":false},{"id":"01a218eb-5631-7a9d-bc82-dca808d3f65e","description":"Um Soar","correct_answer":false},{"id":"01a218eb-5631-7668-b711-1e6c724baec7","description":"Um Pen","correct_answer":false}]},{"id":"01a218eb-5631-75ba-9f7e-b253542715e9","locale":"ptBR","category":"01a2135e-b9ba-7fbd-8736-4a658c8d2151","question":"Qual \u00e9 a palavra para designar um grupo de gatos?","difficulty":3,"explanation":"\u201cClowder\u201d \u00e9 o nome coletivo para gatos; \u201cpride\u201d geralmente se refere a le\u00f5es, enquanto \u201ctroop\u201d costuma se referir a macacos.","alternatives":[{"id":"01a218eb-5631-7790-ab8f-9345054cece8","description":"Um \u201cclowder\u201d","correct_answer":true},{"id":"01a218eb-5631-7400-bce8-77277d6d4147","description":"Uma \u201cmatilha\u201d","correct_answer":false},{"id":"01a218eb-5631-7715-a642-fee16fe79013","description":"Um \u201cpride\u201d","correct_answer":false},{"id":"01a218eb-5631-7052-aaf7-5212d5d1d7f5","description":"Um \u201ctroop\u201d","correct_answer":false}]},{"id":"01a218eb-5631-7be8-8f20-644528d3c76c","locale":"ptBR","category":"01a2135e-b9ba-7fbd-8736-4a658c8d2151","question":"Qual \u00e9 a palavra para designar um grupo de corvos?","difficulty":3,"explanation":"\u201cAn unkindness\u201d \u00e9 um substantivo coletivo tradicional, ou termo de venery, para corvos; muitos nomes de grupos de animais t\u00eam origens igualmente incomuns.","alternatives":[{"id":"01a218eb-5631-71da-88e2-9a5e0f451e7c","description":"Um \u201cunkindness\u201d","correct_answer":true},{"id":"01a218eb-5631-729f-a792-15a7ceddf9ec","description":"Um \u201ccharm\u201d","correct_answer":false},{"id":"01a218eb-5631-7ed8-b407-75c2e5bfefdc","description":"Um \u201crun\u201d","correct_answer":false},{"id":"01a218eb-5631-7943-8102-3ec2324ef316","description":"Um cete","correct_answer":false}]},{"id":"01a218eb-5631-79cf-812a-b71b986934f0","locale":"ptBR","category":"01a2135e-b9ba-7fbd-8736-4a658c8d2151","question":"Em termos m\u00e9dicos, como se chama a condi\u00e7\u00e3o em que um vaso sangu\u00edneo fica obstru\u00eddo por uma bolha de ar que se desloca pela corrente sangu\u00ednea?","difficulty":3,"explanation":"Uma embolia ocorre quando um material transportado pela corrente sangu\u00ednea se aloja em um vaso e o obstrui; o ar \u00e9 uma das poss\u00edveis causas, al\u00e9m dos co\u00e1gulos sangu\u00edneos.","alternatives":[{"id":"01a218eb-5631-77c0-ba41-87fa377e2217","description":"Uma embolia","correct_answer":true},{"id":"01a218eb-5631-7811-9d48-aed592757e25","description":"Um aneurisma","correct_answer":false},{"id":"01a218eb-5631-72fd-9625-0a47dee453e8","description":"Uma hemorragia","correct_answer":false},{"id":"01a218eb-5631-7949-829d-6656992ed9ea","description":"Um AVC","correct_answer":false}]},{"id":"01a218eb-5631-73d3-a062-1f90ece427a0","locale":"ptBR","category":"01a2135e-b9ba-7fbd-8736-4a658c8d2151","question":"Como voc\u00ea chamaria uma am\u00eaijoa beb\u00ea?","difficulty":3,"explanation":"Uma larva \u00e9 um est\u00e1gio imaturo no desenvolvimento de um animal; as am\u00eaijoas jovens passam por um est\u00e1gio de vel\u00edger, no qual nadam livremente, antes de se fixarem.","alternatives":[{"id":"01a218eb-5631-7074-825e-abd8741f673d","description":"Uma larva","correct_answer":true},{"id":"01a218eb-5631-7c90-9985-a0ad70b2988c","description":"Um filhote","correct_answer":false},{"id":"01a218eb-5631-710f-831c-930f9ee870e8","description":"Um cordeiro","correct_answer":false},{"id":"01a218eb-5631-779f-b008-8968092dc40e","description":"Um filhote de canguru","correct_answer":false}]},{"id":"01a218eb-5631-7b2a-a53a-a78c2f99a795","locale":"ptBR","category":"01a2135e-b9ba-7fbd-8736-4a658c8d2151","question":"Como se chama um filhote de alpaca?","difficulty":3,"explanation":"Uma cria \u00e9 um filhote de alpaca ou lhama; a palavra vem do espanhol.","alternatives":[{"id":"01a218eb-5631-7540-947d-d4fcdc44b6b2","description":"Uma cria","correct_answer":true},{"id":"01a218eb-5631-7811-a7c3-991221f6b579","description":"Um patinho","correct_answer":false},{"id":"01a218eb-5631-70d3-aba5-0aa7888fec1e","description":"Um alevino","correct_answer":false},{"id":"01a218eb-5631-73a3-9874-6e3aec9cd3de","description":"Um pintinho","correct_answer":false}]},{"id":"01a218eb-5631-7682-a7d0-ca09809b8b8c","locale":"ptBR","category":"01a2135e-b9ba-7fbd-8736-4a658c8d2151","question":"O que um frenologista analisa?","difficulty":3,"explanation":"Os frenologistas examinavam cr\u00e2nios porque acreditavam que o desenvolvimento cerebral moldava sali\u00eancias que revelavam a personalidade; essa teoria \u00e9 hoje conside